    max_A = []
    def backtrack(current_A, start_val):
        nonlocal max_A
        if len(current_A) > len(max_A):
            max_A = current_A[:]

        for i in range(start_val, n + 1):
            # Check if including i is valid
            valid = True
            # We only need to check triplets involving i
            # So we look for x, y in current_A such that x < y < i
            # and x+y+i is even and x+y > i
            # Wait, the condition is x < y < i, so x+y > i is the forbidden one.
            # Since we are building the set in increasing order, i is the largest.
            # So we need to check if there are x, y in current_A such that 
            # x+y+i is even and x+y > i.
            # Wait, my condition was: x+y+z is even and x+y > z (with z max).
            # If we add i (the largest), the forbidden triplets are (x, y, i)
            # such that x+y+i is even and x+y > i.
            for j in range(len(current_A)):
                for k in range(j + 1, len(current_A)):
                    x = current_A[j]
                    y = current_A[k]
                    if (x + y + i) % 2 == 0 and x + y > i:
                        valid = False
                        break
                if not valid:
                    break

            if valid:
                current_A.append(i)
                backtrack(current_A, i + 1)
                current_A.pop()

    backtrack([], 1)
    return len(max_A)

