def solve_max_bad_set(N):
    triplets = get_forbidden_triplets(N)
    max_size = 0

    # Use a bitmask to represent the set A
    # But N can be up to 2024, so we can't use bitmask for all N.
    # For small N, we can use backtracking.
    def backtrack(idx, current_set):
        nonlocal max_size
        if idx > N:
            max_size = max(max_size, len(current_set))
            return

        if len(current_set) + (N - idx + 1) <= max_size:
            return

        # Try including idx
        can_include = True
        for triplet in triplets:
            if idx in triplet:
                others = [t for t in triplet if t != idx]
                if all(o in current_set for o in others):
                    can_include = False
                    break

        if can_include:
            current_set.add(idx)
            backtrack(idx + 1, current_set)
            current_set.remove(idx)

        # Try excluding idx
        backtrack(idx + 1, current_set)

    backtrack(1, set())
    return max_size

